import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"34、【大壮】 乾下震上","description":"周易阐真 - 34、【大壮】 乾下震上","frontmatter":{"title":"34、【大壮】 乾下震上","description":"周易阐真 - 34、【大壮】 乾下震上"},"headers":[],"relativePath":"zh/classics/chanzhen/035.md","filePath":"zh/classics/chanzhen/035.md"}'),s={name:"zh/classics/chanzhen/035.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：大壮，大者壮也。刚以动，故壮。大壮利贞，大者正也。正大，而天地之情可见矣。</p></blockquote><h1 id="_34、【大壮】-乾下震上" tabindex="-1">34、【大壮】 乾下震上 <a class="header-anchor" href="#_34、【大壮】-乾下震上" aria-label="Permalink to “34、【大壮】 乾下震上”">​</a></h1><p>初九：壮于趾，征凶，有孚。</p><p>九二：贞吉。</p><p>九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。</p><p>九四：贞吉，悔亡。藩决不羸，壮于大舆之复副本。</p><p>六五：丧羊于易，无悔。</p><p>上六：羝羊触藩，不能退，不能遂，无攸利。艰则吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：雷在天上，大壮。君子以非礼弗履。</p><p>大壮者，大其所壮也。上震雷，下乾天，是雷在天上也。雷为刚烈之物，其气最壮，升于天上，震惊一切，壮气更大，此大壮之象也。</p><p>君子有见于此，知雷随时升天，能以生物；人顺理行事，能以立德。以是非礼弗履焉。礼者，动静之节、进退之序，为修身应世之规范。凡人师心自用，任性作为，或妄想贪求，恣情纵欲，皆是非礼。非礼之履，不但不能大，而且不能壮，即或有壮，亦是弃真入假之壮，壮非所壮，大不壮矣。若能非礼勿视，非礼勿听，非礼勿言，非礼勿动，以礼而履，非礼不履，则所履者礼。礼者，理也；理者，天也。履于天理，人欲不生，一步一趋，皆合妙道，与天为徒，与雷同功，居于五行之中，而不为五行所拘，处乎万物之内，而不为万物所伤，其壮顾不大哉!</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>羝，音低。羸，音雷。复副本，音福。</p><p>大壮者，阳气强壮之义。卦德上震动，下乾健，健于内而果于行，健行不息，故为大壮。此进阳壮气之卦，承上恒卦而来。恒者，久于其道之功。久于其道，则身体力行，心坚志远，一念不回，深造自得，是非大壮之人不能也。</p><p>盖大壮之人，自命不凡，俯视一切，放的下，提的起。有大壮之志，即能行大壮之事，作人之所不能作，为人之所不能为，超凡入圣，为天下希有之事，如雷之一动，自地升天，惊愚骇俗，震动一切矣。</p><p>但大壮之道，尤贵壮之得正，若不得正，则壮之不大，其行不利。彼世间旁门外道之徒，着空执相，认假为真，水火不避，患难不惧，有至死不变者，何尝不是壮?其如壮之不正，不但壮不能大，而且因壮伤生，何贵于壮?特以大壮之道，惟利于贞耳。</p><p>贞者，正也，理也。以理而壮，则内有主宰而志正，外无妄动而行正。志正则刚强不屈，万物难移而内壮；行正则果决有断，诸事能成而外壮。志以固其行，行以全其志，内外兼修，不壮者能壮，已壮者能大。已正而壮，其利宁有限量乎？</p><p>初九，在大壮之始，正当虚己求人，究明性命之理而后用。壮者，乃以刚自居，冒然进步，妄想高登，速欲成功，是壮于其趾矣。壮趾之壮，其进锐者，其退速，远行必凶，可于理信之。此不谨于始之壮也。</p><p>九二，刚以治内，柔以应外，外不足而内有余，不壮而壮，壮之有得于中，中而未有不正，正而未有不吉者。此严以治己之壮也。</p><p>九三，躁进无忌，不壮于内而壮于外，小人以是而贪图名利可也。至于修道君子，所当万有皆空，而亦用壮于外，其壮罔用，不特壮不得正，即得其正，未取于彼，先伤于我，亦是危厉之道。如羝羊触藩，必羸败其角。此刚而务外之壮也。</p><p>九四，刚而能柔，阴阳混合，金丹已结，所当正己之后、正人之时，是以贞吉而又悔亡也。贞吉者，正己之吉。悔亡者，正人之悔亡。又近六五，虚心下贤之知音，不但不败其己之壮，而且能大人之壮，如藩决不羸，壮于大舆之复副本。此正己正人之壮也。</p><p>六五，居于动体，柔而无刚，时在可壮，人不能壮，如丧羊于平易之地矣。然虽人不能壮，幸其柔顺虚心，借他人之知识，以开自己之茅塞。虚心即能实腹，不壮者能壮，既壮者能大，可无丧羊之悔矣。此己不壮而借人之壮也。</p><p>上六，愚而自用，妄猜私议，入于旁门，到得年满月尽，生平所学，俱归无用，如羝羊触藩，不能退、不能遂矣。居动之极，祸已酿成，如何能退?在事之终，后悔不及，如何能遂?退之不能，遂之不得，空空一世，有何利乎?然则柔而无能者，与其自己用壮而受害，不若及早虚心求师，困而学之，勉强而行之，从艰难处下一番死功夫，不患不到大壮之地。此本不壮，而归正即壮也。</p><p>六爻皆有壮道，吉凶不一。求其壮于内，而能正己者，其惟九二；壮于外而能正人者，其惟九四乎？</p><p>然则修道者，当未了道，必先正己；既已了道，又须正人。正己者，修道也；正人者，立德也。修道立德，方是壮之正、壮之大。大壮之利贞，必以道全德备为极功也。</p>',26)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
